<script setup>
import IeltsNavigation from '../components/IeltsNavigation.vue'
import {ref,onMounted,onBeforeUnmount} from 'vue'
import ielts,{fetchMedia,requestKey} from '../api/ielts.js'
const ability=ref('recognition'),questions=ref([]),index=ref(0),answer=ref(''),result=ref(null),error=ref(''),busy=ref(false),audio=ref(null)
const names={recognition:'识义',listening:'听辨',spelling:'拼写',collocation:'搭配',paraphrase:'同义替换'}
let key=requestKey(),audioUrl=''
async function load(){error.value='';result.value=null;index.value=0;answer.value='';try{questions.value=(await ielts.vocabulary(ability.value)).questions;key=requestKey()}catch(e){error.value=e.message}}
async function submit(){if(!answer.value.trim())return;busy.value=true;error.value='';try{result.value=await ielts.vocabularyAnswer({cardId:questions.value[index.value].id,ability:ability.value,answer:answer.value,requestKey:key})}catch(e){error.value=e.message}finally{busy.value=false}}
function next(){audio.value?.pause();result.value=null;answer.value='';index.value=(index.value+1)%questions.value.length;key=requestKey()}
async function listen(){try{if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=await fetchMedia(questions.value[index.value].audioPath);audio.value=new Audio(audioUrl);await audio.value.play()}catch(e){error.value=e.message}}
onMounted(load);onBeforeUnmount(()=>{audio.value?.pause();if(audioUrl)URL.revokeObjectURL(audioUrl)})
</script>
<template><div class="ielts-page"><IeltsNavigation/><header class="ielts-heading"><div><h1>把一个词真正学会</h1><p>分别练习识义、听辨、拼写、搭配和同义替换。</p></div><router-link class="btn btn-ghost" to="/ielts/records">学习档案</router-link></header><div class="ielts-tabs" role="tablist" aria-label="训练能力"><button v-for="(name,value) in names" :key="value" class="btn btn-ghost" :aria-selected="ability===value" role="tab" :disabled="busy" @click="ability=value;load()">{{name}}</button></div><p v-if="error" class="ielts-error" role="alert">{{error}}</p><form v-if="questions[index]" class="ielts-vocab" @submit.prevent="submit"><p class="muted">{{index+1}} / {{questions.length}} · {{names[ability]}}</p><h2 class="prompt">{{questions[index].prompt}}</h2><p v-if="questions[index].context">{{questions[index].context}}</p><button v-if="ability==='listening'" type="button" class="btn btn-ghost" @click="listen">播放单词发音</button><div class="ielts-answer"><div v-if="questions[index].options" class="ielts-options"><label v-for="option in questions[index].options" :key="option.value"><input v-model="answer" type="radio" :value="option.value" :disabled="!!result">{{option.label}}</label></div><input v-else v-model="answer" aria-label="写出答案" autocomplete="off" autocapitalize="off" :spellcheck="false" :disabled="!!result"></div><button v-if="!result" class="btn btn-primary" :disabled="busy||!answer.trim()" style="margin-top:24px">检查答案</button><div v-if="result" class="ielts-result" :class="{wrong:!result.correct}"><strong>{{result.correct?'答对了':'再记住这个表达'}}</strong><p>{{result.card.word}}：{{result.card.meaning}}</p><p>{{result.card.collocation}}</p><p>{{result.card.example}}</p><p>当前题目答案：{{result.expected}}</p><p class="muted">本次只记入{{names[ability]}}能力，不会改变其他能力的记录。</p></div><button v-if="result" type="button" class="btn btn-primary" style="margin-top:20px" @click="next">下一个词</button></form></div></template>
